DECLARE packs jsonb := $pack$[{"codigo":"S22F-C01","legacy_id":86,"legacy_ids":[86,100],"relacionadas":["S9-C06","S8-C07","S9-C09"],"residual":"","coberturas":[{"legacy_id":86,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"En instrumentación de comportamiento del onboarding BLOQUEAR instalación directa en código de scripts de analytics, heatmaps o tracking de terceros fuera del contenedor autorizado GTM, o instrumentación GA4 que no utilice GTM como medio de implementación. GA4 es herramienta principal de medición de comportamiento; no concede permiso de datos ni de tags nuevos. S9-C06 conserva dataLayer y prohibición de lectura DOM; S8-C07 conserva privacidad. Binding pendiente. La exclusividad general fuera del onboarding queda residual para 100."},{"legacy_id":100,"estado_cobertura":"PARCIAL","residual":"Falta acreditar aplicación exclusiva del contenedor GTM a las demás superficies Cliente, B2B y terceros, no solo onboarding.","diferencias":"En instrumentación de comportamiento del onboarding BLOQUEAR instalación directa en código de scripts de analytics, heatmaps o tracking de terceros fuera del contenedor autorizado GTM, o instrumentación GA4 que no utilice GTM como medio de implementación. GA4 es herramienta principal de medición de comportamiento; no concede permiso de datos ni de tags nuevos. S9-C06 conserva dataLayer y prohibición de lectura DOM; S8-C07 conserva privacidad. Binding pendiente. La exclusividad general fuera del onboarding queda residual para 100."}],"hechos":["s22f01_instrumentacion_onboarding","s22f01_script_directo","s22f01_contenedor_no_autorizado","s22f01_ga4_sin_gtm"],"paquete":{"tipo":"NUEVA","codigo":"S22F-C01","clave":"s22f_legacy_86","familia":"ANALYTICS","naturaleza":"CONDUCTA","clase":"TRANSVERSAL","alcance":"BACKEND","modo":"HEREDA","dueno":"TECNICO","titulo":"Instrumentación onboarding a través de GTM autorizado","descripcion":"En instrumentación de comportamiento del onboarding BLOQUEAR instalación directa en cód