so que eluda Cloudflare como perímetro WAF y protección DDoS; conservar caché de assets estáticos donde corresponda. BLOQUEAR configuración WAF que carezca de controles activos de inyección SQL, XSS en formularios, escaneo de rutas o desafío de IP de países sin operación. No inventar países, umbrales ni afirmar que infraestructura está desplegada. Binding pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/133;lf_ops.reglas/134","solicitante":"Cristhian / Claude S22-F 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22f03_trafico_o_config_produccion"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22f03_elude_perimetro"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22f03_proteccion_o_cache_invalida"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22f03_control_waf_ausente"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22f03_trafico_o_config_produccion":true,"s22f03_elude_perimetro":false,"s22f03_proteccion_o_cache_invalida":false,"s22f03_control_waf_ausente":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22f03_trafico_o_config_produccion":true,"s22f03_elude_perimetro":true,"s22f03_proteccion_o_cache_invalida":false,"s22f03_control_waf_ausente":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22f03_trafico_o_config_produccion":true,"s22f03_elude_perimetro":false,"s22f03_proteccion_o_cache_invalida":true,"s22f03_control_waf_ausente":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22f03_trafico_o_config_produccion":true,"s22f03_elude_perimetro":false,"s22f03_proteccion_o_cache_invalida":false,"s22f03_control_waf_ausente":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22f03_trafico_o_config_produccion":false,"s22f03_elude_perimetro":true,"s22f03_proteccion_o_cache_invalida":true,"s22f03_control_waf_ausente":true},"esperado":false}]},"hash":"9cbe6574b76634774b14535cb48dec7b4252678bc4769e9e908e31423d44e077","hash_paquete":"b7cb74a8a95a07790babc529b83461c70e1f71828eb874b2046d659aed18a7ec","hash_evaluado":"9cbe6574b7","hash_paquete_10":"b7cb74a8a9"},{"codigo":"S22F-C04","legacy_id":158,"legacy_ids":[158],"relacionadas":["S22B-C03","M2L2-C06"],"residual":"Falta reconciliar la fecha histórica de primera cuota cargada por aliado con la obligación vigente de pago inicial inmediato en checkout; no modifica esa obligación.","coberturas":[{"legacy_id":158,"estado_cobertura":"PARCIAL","residual":"Falta reconciliar la fecha histórica de primera cuota cargada por aliado con la obligación vigente de pago inicial inmediato en checkout; no modifica esa obligación.","diferencias":"Al presentar fecha de primera cuota de oferta en cuotas BLOQUEAR fecha calculada o inventada por LF en lugar de campo autorizado por aliado B2B. Si campo es nulo, presentar A coordinar con el aliado, no inferir fecha. No cambia exigencia de pago inicial en checkout de S22B-C03; la fecha presentada no autoriza diferir ese pago. Binding pendiente."}],"hechos":["s22f04_presenta_fecha_primera_cuota","s22f04_fecha_no_autorizada","s22f04_campo_nulo","s22f04_mensaje_nulo_invalido"],"paquete":{"tipo":"NUEVA","codigo":"S22F-C04","clave":"s22f_legacy_158","familia":"OFFERS_INSTALLMENTS","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_PAYMENTS","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Origen de fecha contractual de primera cuota","descripcion":"Al presentar fecha de primera cuota de oferta en cuotas BLOQUEAR fecha calculada o inventada por LF en lugar de campo autorizado por aliado B2B. Si campo es nulo, presentar A coordinar con el aliado, no inferir fecha. No cambia exigencia de pago inicial en checkout de S22B-C03; la fecha presentada no autoriza diferir ese pago. Binding pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/158","solicitante":"Cristhian / Claude S22-F 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22f04_presenta_fecha_primera_cuota"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22f04_fecha_no_autorizada"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22f04_campo_nulo"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22f04_mensaje_nulo_invalido"},"der":{"lit":true}}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22f04_presenta_fecha_primera_cuota":true,"s22f04_fecha_no_autorizada":false,"s22f04_campo_nulo":false,"s22f04_mensaje_nulo_invalido":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22f04_presenta_fecha_primera_cuota":true,"s22f04_fecha_no_autorizada":true,"s22f04_campo_nulo":false,"s22f04_mensaje_nulo_invalido":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22f04_presenta_fecha_primera_cuota":true,"s22f04_fecha_no_autorizada":false,"s22f04_campo_nulo":true,"s22f04_mensaje_nulo_invalido":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22f04_presenta_fecha_primera_cuota":true,"s22f04_fecha_no_autorizada":false,"s22f04_campo_nulo":true,"s22f04_mensaje_nulo_invalido":false},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22f04_presenta_fecha_primera_cuota":false,"s22f04_fecha_no_autorizada":true,"s22f04_campo_nulo":true,"s22f04_mensaje_nulo_invalido":true},"esperado":false}]},"hash":"2b4e9c6829ead5cbc5b04d039ef48572a7543f60760e4ba94e98cbdb3b8cf716","hash_paquete":"7a8b40464867d0ac28e6fd5782bf12d65abf313f0ebda03e8cf3c479ee23bcb9","hash_evaluado":"2b4e9c6829","hash_paquete_10":"7a8b404648"}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 n:=n+1;
 END LOOP;
 IF n<>4 OR vectors<>21 THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S22F proposal-only: independent judgment pending';
END $s22$;
COMMIT;
